import os

data_dir = "/home/chatbot/Projects/ChatbotAI/data/"

def update_file(filename, replacements):
    filepath = os.path.join(data_dir, filename)
    if not os.path.exists(filepath):
        print(f"Error: {filepath} does not exist.")
        return False
        
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()
        
    original_len = len(content)
    updated = False
    for target, replacement in replacements:
        if target in content:
            content = content.replace(target, replacement)
            updated = True
        else:
            print(f"Warning: Target text not found in {filename}:\n{target[:100]}...")
            
    if updated:
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"Successfully updated {filename}. Length changed from {original_len} to {len(content)}.")
        return True
    else:
        print(f"No updates made to {filename}.")
        return False

